module elevator_controller (
    input clk, reset,
    input up_request, down_request,
    output [1:0] state
);
    // State definitions
    localparam IDLE  = 2'b00;
    localparam MOVING = 2'b01;
    localparam STOPPED = 2'b10;

    // Next state logic
    reg [1:0] next_state;

    always @* begin
        case ({up_request, down_request})
            2'b11: next_state = STOPPED;
            2'b10: next_state = MOVING;
            2'b01: next_state = IDLE;
            default: next_state = IDLE;
        endcase
    end

    // State register with synchronous reset
    reg [1:0] state;

    always @(posedge clk or posedge reset) begin
        if (reset)
            state <= IDLE;
        else
            state <= next_state;
    end

    // Assign outputs based on current state
    assign out_xnor = (state == IDLE);
    assign out_and  = (state == MOVING);
    assign out_anotb = (state == STOPPED);
    assign out_or   = (state == IDLE || state == MOVING);
    assign out_nand = (state == STOPPED);
    assign out_nor  = (state == IDLE);

endmodule

