module TopModule (
  input clk,
  input in,
  input reset,
  output done
);

  localparam [1:0] IDLE = 2'b00,
                   STEP1 = 2'b01,
                   STEP2 = 2'b10,
                   DONE = 2'b11;

  reg [1:0] current_state, next_state;
  reg [31:0] counter;

  // State transition
  always @(posedge clk) begin
    if (reset) begin
      current_state <= IDLE;
    end else begin
      current_state <= next_state;
    end
  end

  // Next state logic
  always @(*) begin
    case (current_state)
      IDLE: next_state = in[3] ? STEP1 : IDLE;
      STEP1: next_state = in[3] ? STEP1 : STEP2;
      STEP2: next_state = in[3] ? DONE : IDLE;
      DONE: next_state = DONE;
      default: next_state = IDLE;
    endcase
  end

  // Counter logic
  always @(posedge clk) begin
    if (reset) begin
      counter <= 0;
    end else if (current_state == DONE) begin
      counter <= counter + 1;
    end else begin
      counter <= 0;
    end
  end

  // Output assignment
  assign done = (current_state == DONE);

endmodule

